"""
RELIC V2 evaluation (development-set replay).

Replays the committed benchmark (results/final/raw/evaluation_records.jsonl)
with the V2 detector and its ablations, WITHOUT touching results/final/:

* mutant texts are regenerated by ``relic_eval.mutate.generate`` and verified
  against the committed ``mutant_sha256`` (any mismatch aborts the run);
* oracle labels / statuses are taken from the committed records unchanged
  (the oracle is not re-run and never sees any detector output);
* RELIC v1.1 is recomputed and must equal the committed predictions;
* v1.0.0, baselines A/B/E and the text-change reference use the committed
  predictions as they are.

Outputs (results/v2/, deterministic apart from v2_run_info.json):
  v2_metrics.json        all metrics, CIs, ablation, flips, recovery, diagnostics
  v2_predictions.jsonl   one line per evaluable mutant, every detector's flag

IMPORTANT: every subject here is a *development* subject (the defects were
found by inspecting these very files). The numbers are therefore development
results, not an external validation; see ``validation_status`` in the output.

Run:  python -m relic_eval.v2_eval
"""

from __future__ import annotations

import argparse
import hashlib
import json
import platform
import subprocess
import sys
from collections import Counter, defaultdict
from datetime import datetime, timezone

from jcl_oracle.judge import describe_file
from legacy_contract.bcg.builder import BCGBuilder
from legacy_contract.parsers.jcl_parser import JCLParser
from legacy_contract.risk.detector import RiskDetector
from legacy_contract.static_analysis.extractor import StaticContractExtractor
from relic_eval.contract_recovery import relic_pairs
from relic_eval.detectors import Prediction, RelicDetector, neutral_record
from relic_eval.metrics import Confusion, cluster_bootstrap, confusion
from relic_eval.mutate import generate
from relic_eval.subjects import ROOT, get_subjects

OUT = ROOT / "results" / "v2"
RECORDS = ROOT / "results" / "final" / "raw" / "evaluation_records.jsonl"
LLM_RECORDS = ROOT / "results" / "final" / "raw" / "llm_records.jsonl"

COMMITTED = ["relic_v1_0", "static_bcg_E", "structural_A", "complexity_B", "textdiff"]
FIXES = ("D001", "D002", "D003", "D004")
V2_VARIANTS = ["relic_v2"] + [f"relic_v2_wo_{f}" for f in FIXES]
DIAGNOSTIC = ["textdiff_ignore_job_parameters"]
DETECTORS = ["relic_v1_0", "relic_v1_1"] + V2_VARIANTS + COMMITTED[1:] + DIAGNOSTIC
POPULATIONS = ["carddemo", "genapp", "omp_course", "pooled"]


def _sha(text: str) -> str:
    return hashlib.sha256(text.encode()).hexdigest()[:16]


# ---------------------------------------------------------------------------
# detectors
# ---------------------------------------------------------------------------

class AblatedV2Detector:
    """RELIC V2 with exactly one fix (D-001 .. D-004) switched off (ablation)."""

    def __init__(self, name: str, off: str) -> None:
        if off not in FIXES:
            raise ValueError(off)
        self.name = name
        self.off = off

    def _bcg(self, text: str, path: str):
        parser = JCLParser(v2_fixes=True)
        parser.v2_step_identity = self.off != "D001"
        parser.v2_dd_parsing = self.off != "D002"
        parser.v2_delete_disp = self.off != "D004"
        _res, ir = parser.parse_lines(text.splitlines(), path)
        extractor = StaticContractExtractor(v2_fixes=True, v2_resource_order=self.off != "D003")
        return BCGBuilder().build(ir, extractor.extract(ir))

    def predict(self, original: str, mutated: str, path: str) -> Prediction:
        try:
            rep = RiskDetector().detect(self._bcg(original, path), self._bcg(mutated, path),
                                        neutral_record())
            return Prediction(len(rep.risk_items) + len(rep.false_positive_candidates) > 0)
        except Exception as exc:  # recorded, scored as "not flagged"
            return Prediction(None, "ERROR", {"error": repr(exc)[:300]})


def _normalise_job_parameters(text: str) -> list[str]:
    """Lines of ``text`` without comment statements; every JOB statement is
    reduced to ``//NAME JOB`` (its parameters and continuation lines ignored)."""
    out: list[str] = []
    in_job = False
    for line in text.splitlines():
        if line.startswith("//*"):
            continue
        body = line[:71].rstrip() if line.startswith("//") else line.rstrip()
        if in_job:                      # continuation of the JOB statement
            in_job = body.endswith(",")
            continue
        parts = body.split()
        if body.startswith("//") and len(parts) >= 2 and parts[1] == "JOB":
            in_job = body.endswith(",")
            out.append(f"{parts[0]} JOB")
            continue
        out.append(body)
    return out


class TextDiffIgnoreJobCard:
    """
    DIAGNOSTIC ONLY (post hoc, not a competing detector): flags any change
    outside comment statements and outside the PARAMETERS of JOB statements
    (a JOB statement's existence and name still count). It exists to show how
    much of the benchmark's specificity is attainable with no understanding of
    JCL semantics (both negative operators edit only comments or JOB
    parameters).
    """
    name = "textdiff_ignore_job_parameters"

    def predict(self, original: str, mutated: str, path: str) -> Prediction:
        return Prediction(_normalise_job_parameters(original) != _normalise_job_parameters(mutated))


# ---------------------------------------------------------------------------
# replay
# ---------------------------------------------------------------------------

def load_records() -> dict[str, dict]:
    with open(RECORDS) as fh:
        return {r["mutation_id"]: r for r in map(json.loads, fh)}


def iter_mutants(records: dict[str, dict]):
    """Yield (record, original, mutated, artifact_path) for every EVALUABLE mutant."""
    seen = set()
    for subject in get_subjects(None):
        for f in subject.jcl_files:
            original = f.read_text(errors="replace")
            rel = subject.rel(f)
            idx: dict[str, int] = {}
            for mu in generate(original):
                i = idx.get(mu.operator, 0)
                idx[mu.operator] = i + 1
                mid = f"{subject.key}/{rel}/{mu.operator}/{i}"
                rec = records[mid]
                if mu.text is None:
                    continue
                if _sha(mu.text) != rec["mutant_sha256"]:
                    raise RuntimeError(f"mutant regeneration differs from committed record: {mid}")
                seen.add(mid)
                if rec["status"] == "EVALUABLE":
                    yield rec, original, mu.text, subject.artifact_path(f)
    missing = [m for m, r in records.items() if r["status"] == "EVALUABLE" and m not in seen]
    if missing:
        raise RuntimeError(f"{len(missing)} evaluable committed mutants were not regenerated")


def replay(records: dict[str, dict]) -> list[dict]:
    live = {
        "relic_v1_1": RelicDetector(legacy_v1_0=False),
        "relic_v2": RelicDetector(legacy_v1_0=False, v2=True),
        **{f"relic_v2_wo_{f}": AblatedV2Detector(f"relic_v2_wo_{f}", f) for f in FIXES},
        "textdiff_ignore_job_parameters": TextDiffIgnoreJobCard(),
    }
    rows: list[dict] = []
    for rec, original, mutated, path in iter_mutants(records):
        pred = {d: rec["predictions"].get(d) for d in COMMITTED}
        for name, det in live.items():
            pred[name] = det.predict(original, mutated, path).flagged
        if pred["relic_v1_1"] != rec["predictions"]["relic_v1_1"]:
            raise RuntimeError(f"recomputed relic_v1_1 differs from committed: {rec['mutation_id']}")
        rows.append({
            "mutation_id": rec["mutation_id"], "subject": rec["subject_system"], "file": rec["file"],
            "operator": rec["mutation_type"], "contract_type": rec["contract_type"],
            "truth": bool(rec["ground_truth"]), "pred": pred,
            "cluster": f"{rec['subject_system']}/{rec['file']}",
        })
    rows.sort(key=lambda r: r["mutation_id"])
    return rows


# ---------------------------------------------------------------------------
# metrics
# ---------------------------------------------------------------------------

def _pop(rows: list[dict], pop: str) -> list[dict]:
    return rows if pop == "pooled" else [r for r in rows if r["subject"] == pop]


def _compact(d: dict) -> dict:
    return {k: d[k] for k in ("tp", "fp", "fn", "tn", "precision", "recall", "f1", "specificity")}


def metrics_blocks(rows: list[dict]) -> dict:
    out: dict = {"populations": {}, "per_operator": {}, "per_contract_type": {}}
    pairs = [("relic_v2", "relic_v1_1"), ("relic_v2", "relic_v1_0"), ("relic_v2", "textdiff"),
             *[("relic_v2", f"relic_v2_wo_{f}") for f in FIXES]]
    for pop in POPULATIONS:
        rs = _pop(rows, pop)
        out["populations"][pop] = {
            "n": len(rs), "positives": sum(r["truth"] for r in rs),
            "negatives": sum(not r["truth"] for r in rs),
            "n_files": len({r["cluster"] for r in rs}),
            "detectors": {d: confusion(rs, d).as_dict() for d in DETECTORS},
            "bootstrap": cluster_bootstrap(rs, DETECTORS, pairs),
        }
        for key, field in (("per_operator", "operator"), ("per_contract_type", "contract_type")):
            block: dict = {}
            for v in sorted({r[field] for r in rs}):
                sub = [r for r in rs if r[field] == v]
                block[v] = {d: _compact(confusion(sub, d).as_dict())
                            for d in ("relic_v1_1", "relic_v2", "textdiff")}
            out[key][pop] = block
    return out


def flips(rows: list[dict]) -> dict:
    gained = [r["mutation_id"] for r in rows if r["pred"]["relic_v2"] and not r["pred"]["relic_v1_1"]]
    lost = [r["mutation_id"] for r in rows if r["pred"]["relic_v1_1"] and not r["pred"]["relic_v2"]]
    truth = {r["mutation_id"]: r["truth"] for r in rows}
    return {
        "gained_flags": gained, "lost_flags": lost,
        "gained_true_positives": sum(truth[m] for m in gained),
        "gained_false_positives": sum(not truth[m] for m in gained),
        "lost_true_positives": sum(truth[m] for m in lost),
        "lost_false_positives_removed": sum(not truth[m] for m in lost),
        "remaining_false_negatives_v2": sorted(
            r["mutation_id"] for r in rows if r["truth"] and not r["pred"]["relic_v2"]),
        "remaining_false_positives_v2": sorted(
            r["mutation_id"] for r in rows if not r["truth"] and r["pred"]["relic_v2"]),
    }


def recall_by_duplicate_names(rows: list[dict]) -> dict:
    """Recall of v1.1 vs v2 on positives, split by whether the file reuses step names."""
    cache: dict[str, bool] = {}
    paths = {f"{s.key}/{s.rel(f)}": f for s in get_subjects(None) for f in s.jcl_files}

    def dup(file_key: str) -> bool:
        if file_key not in cache:
            text = paths[file_key].read_text(errors="replace")
            res, _ = JCLParser().parse_lines(text.splitlines(), file_key)
            names = [t.name.upper() for t in res.tokens if t.operation == "EXEC" and t.name]
            cache[file_key] = len(names) != len(set(names))
        return cache[file_key]

    out: dict = {}
    for label, flag in (("files_with_duplicate_step_names", True),
                        ("files_without_duplicate_step_names", False)):
        sub = [r for r in rows if r["truth"] and dup(r["cluster"]) is flag]
        out[label] = {
            "n_files": len({r["cluster"] for r in sub}),
            "positives": len(sub),
            "relic_v1_1_recall": confusion(sub, "relic_v1_1").as_dict()["recall"],
            "relic_v2_recall": confusion(sub, "relic_v2").as_dict()["recall"],
        }
    return out


# ---------------------------------------------------------------------------
# contract recovery (RESOURCE / CONTROL_FLOW / TEMPORAL against oracle facts)
# ---------------------------------------------------------------------------

def relic_pairs_v2(text: str, path: str, off: str | None = None) -> dict[str, set[tuple[str, str]]]:
    """Like contract_recovery.relic_pairs but with V2 parsing; step names are
    mapped back to their declared names so they stay comparable with the
    oracle's name-level facts."""
    parser = JCLParser(v2_fixes=True)
    parser.v2_step_identity = off != "D001"
    parser.v2_dd_parsing = off != "D002"
    parser.v2_delete_disp = off != "D004"
    _r, ir = parser.parse_lines(text.splitlines(), path)
    res = StaticContractExtractor(v2_fixes=True, v2_resource_order=off != "D003").extract(ir)
    names = {eid: str(e.attributes.get("base_name", e.name)) for eid, e in ir.entities.items()}
    out: dict[str, set[tuple[str, str]]] = {"TEMPORAL": set(), "RESOURCE": set(), "CONTROL_FLOW": set()}
    for c in res.all_contracts:
        a, b = names.get(c.subject_id, c.subject_id), names.get(c.object_id, c.object_id)
        if a != b:
            out[c.contract_type.value].add((a, b))
    return out


def contract_recovery() -> dict:
    result: dict = {}
    for subject in get_subjects(None):
        totals: dict[str, dict[str, Confusion]] = {}
        for f in subject.jcl_files:
            text = f.read_text(errors="replace")
            ap = subject.artifact_path(f)
            facts = describe_file(text, subject.proclib, subject.cobol_sources)
            truth = {"TEMPORAL": facts.order_pairs, "RESOURCE": facts.dataflow_pairs,
                     "CONTROL_FLOW": facts.cond_pairs}
            for version, pred in (("relic_v1_1", relic_pairs(text, ap, False)),
                                  ("relic_v2", relic_pairs_v2(text, ap)),
                                  *[(f"relic_v2_wo_{f}", relic_pairs_v2(text, ap, f)) for f in FIXES]):
                for ctype, t in truth.items():
                    p = pred[ctype]
                    c = totals.setdefault(version, {}).setdefault(ctype, Confusion())
                    c.tp += len(p & t)
                    c.fp += len(p - t)
                    c.fn += len(t - p)
        result[subject.key] = {v: {ct: _compact(c.as_dict()) for ct, c in d.items()}
                               for v, d in totals.items()}
    return result


# ---------------------------------------------------------------------------
# diagnostics: benchmark adequacy, LLM selection bias
# ---------------------------------------------------------------------------

def benchmark_adequacy(rows: list[dict]) -> dict:
    neg = [r for r in rows if not r["truth"]]
    by_op = Counter(r["operator"] for r in neg)
    cosmetic = by_op["INSERT_COMMENT"] + by_op["CHANGE_MSGCLASS"]
    return {
        "negatives": len(neg),
        "negatives_by_operator": dict(sorted(by_op.items())),
        "negatives_that_are_cosmetic_comment_or_msgclass": cosmetic,
        "negatives_that_are_other": len(neg) - cosmetic,
        "positives_by_operator": dict(sorted(Counter(r["operator"] for r in rows if r["truth"]).items())),
        "operators_with_zero_evaluable_mutants": ["REMOVE_IF_GUARD"],
        "note": ("All evaluable behaviour-preserving mutants are comment insertions or MSGCLASS "
                 "edits, except COND edits whose guarded step cannot be bypassed in any modelled "
                 "scenario. Specificity therefore measures 'does not fire on cosmetic edits', not "
                 "semantic-equivalence reasoning."),
    }


def llm_selection(rows: list[dict]) -> dict:
    """Quantify who the LLM comparison actually scored, from committed records only."""
    if not LLM_RECORDS.exists():
        return {"available": False}
    by_mut: dict[str, dict[str, dict]] = defaultdict(dict)
    with open(LLM_RECORDS) as fh:
        for r in map(json.loads, fh):
            by_mut[r["mutation_id"]][r["baseline"]] = r
    status = Counter((b, r["status"]) for d in by_mut.values() for b, r in d.items())
    reasons = Counter((b, r["status"], (r.get("reason") or "")[:60])
                      for d in by_mut.values() for b, r in d.items() if r["status"] != "OK")
    truth = {r["mutation_id"]: r for r in rows}
    scored = {m for m, d in by_mut.items() if m in truth and len(d) == 2
              and all(x["status"] == "OK" for x in d.values())}
    unscored = {m for m in truth if m not in scored}

    def prof(ids):
        n = len(ids)
        return {
            "n": n,
            "positive_share": round(sum(truth[m]["truth"] for m in ids) / n, 4) if n else None,
            "by_operator": dict(sorted(Counter(truth[m]["operator"] for m in ids).items())),
            "by_subject": dict(sorted(Counter(truth[m]["subject"] for m in ids).items())),
        }

    def llm_conf(baseline: str, invalid_as: bool) -> dict:
        recs = []
        for m, row in truth.items():
            r = by_mut.get(m, {}).get(baseline)
            p = r["flagged"] if r and r["status"] == "OK" else invalid_as
            recs.append({"truth": row["truth"], "pred": {"x": bool(p)}})
        return _compact(confusion(recs, "x").as_dict())

    common = []
    for m in sorted(scored):
        pred = dict(truth[m]["pred"])
        pred["llm_C"] = by_mut[m]["llm_C"]["flagged"]
        pred["llm_D"] = by_mut[m]["llm_D"]["flagged"]
        common.append({"truth": truth[m]["truth"], "pred": pred})
    common_scored = {
        d: _compact(confusion(common, d).as_dict())
        for d in ("relic_v1_0", "relic_v1_1", "relic_v2", "textdiff", "llm_C", "llm_D")
    }
    return {
        "available": True,
        "common_scored_subset_metrics": common_scored,
        "common_scored_subset_note": (
            "Selection-biased: restricted to mutants where BOTH LLM baselines returned parseable "
            "output (not a random subsample). Positive share differs from the full benchmark."),
        "status_counts": {f"{b}:{s}": n for (b, s), n in sorted(status.items())},
        "non_ok_reasons": {f"{b}:{s}:{rsn}": n for (b, s, rsn), n in sorted(reasons.items())},
        "scored_on_both_baselines": prof(scored),
        "not_scored": prof(unscored),
        "llm_bounds_on_all_evaluable": {
            "llm_C_invalid_as_not_flagged": llm_conf("llm_C", False),
            "llm_C_invalid_as_flagged": llm_conf("llm_C", True),
            "llm_D_invalid_as_not_flagged": llm_conf("llm_D", False),
            "llm_D_invalid_as_flagged": llm_conf("llm_D", True),
        },
        "relic_v1_0_all_evaluable": _compact(confusion(rows, "relic_v1_0").as_dict()),
        "relic_v2_all_evaluable": _compact(confusion(rows, "relic_v2").as_dict()),
    }


# ---------------------------------------------------------------------------

def run() -> dict:
    records = load_records()
    rows = replay(records)
    metrics = {
        "schema": "relic-v2-metrics/1",
        "validation_status": (
            "DEVELOPMENT ONLY. Every subject below (CardDemo, OMP COBOL course, GenApp) was inspected "
            "while diagnosing defects and choosing fixes; none is a held-out set. No genuinely "
            "independent held-out dataset or independent reviewer was available: EXTERNAL VALIDATION "
            "REMAINS PENDING."),
        "oracle": "unchanged: labels and statuses are the committed results/final records",
        "n_evaluable_replayed": len(rows),
        "detectors": DETECTORS,
        "detector_notes": {
            "relic_v1_0": "committed predictions (primary detector of results/final)",
            "relic_v1_1": "recomputed; verified equal to committed predictions",
            "relic_v2": "v1.1 + D-001 step identity + D-002 DD parsing + D-003 producer-before-consumer "
                        "+ D-004 DISP=(MOD,DELETE) idiom (opt-in v2_fixes)",
            **{f"relic_v2_wo_{f}": f"ablation: V2 without {f[0]}-{f[1:]}" for f in FIXES},
            "textdiff_ignore_job_parameters": "post-hoc diagnostic, not a competing detector",
        },
        **metrics_blocks(rows),
        "flips_v2_vs_v1_1": flips(rows),
        "recall_by_duplicate_step_names": recall_by_duplicate_names(rows),
        "contract_recovery": contract_recovery(),
        "benchmark_adequacy": benchmark_adequacy(rows),
        "llm_selection_analysis": llm_selection(rows),
    }
    return {"metrics": metrics, "rows": rows}


def write(result: dict) -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    with open(OUT / "v2_metrics.json", "w") as fh:
        json.dump(result["metrics"], fh, indent=2, sort_keys=True)
        fh.write("\n")
    with open(OUT / "v2_predictions.jsonl", "w") as fh:
        for r in result["rows"]:
            fh.write(json.dumps({k: r[k] for k in ("mutation_id", "operator", "contract_type",
                                                   "truth", "pred")}, sort_keys=True) + "\n")
    try:
        commit = subprocess.run(["git", "rev-parse", "HEAD"], cwd=ROOT, capture_output=True,
                                text=True, check=False).stdout.strip() or None
    except OSError:
        commit = None
    with open(OUT / "v2_run_info.json", "w") as fh:
        json.dump({"timestamp_utc": datetime.now(timezone.utc).isoformat(timespec="seconds"),
                   "python": sys.version.split()[0], "platform": platform.platform(),
                   "git_commit": commit}, fh, indent=2, sort_keys=True)
        fh.write("\n")


def main(argv: list[str] | None = None) -> None:
    argparse.ArgumentParser(description=__doc__.splitlines()[1]).parse_args(argv)
    result = run()
    write(result)
    p = result["metrics"]["populations"]["pooled"]["detectors"]
    for d in ("relic_v1_0", "relic_v1_1", *V2_VARIANTS,
              "textdiff", "textdiff_ignore_job_parameters"):
        c = p[d]
        print(f"{d:24s} TP {c['tp']:3d} FP {c['fp']:2d} FN {c['fn']:3d} TN {c['tn']:3d}  "
              f"P {c['precision']}  R {c['recall']}  F1 {c['f1']}")


if __name__ == "__main__":
    main()
